import{_ as d,o as r,c as n,a2 as s}from"./chunks/framework.BqNd1sPY.js";const l=JSON.parse('{"title":"术语速查","description":"","frontmatter":{},"headers":[],"relativePath":"05-速查表/术语速查.md","filePath":"05-速查表/术语速查.md"}'),a={name:"05-速查表/术语速查.md"};function o(e,t,p,i,g,m){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="术语速查" tabindex="-1">术语速查 <a class="header-anchor" href="#术语速查" aria-label="Permalink to &quot;术语速查&quot;">​</a></h1><p>课程正文中的核心术语与本页保持同一份定义。每个词条都包含一句话解释和最常见的误解。</p><table tabindex="0"><thead><tr><th>术语</th><th>一句话解释</th><th>不要误解为</th></tr></thead><tbody><tr><td><span id="term-token"></span><strong>token（词元）</strong></td><td>文本经过分词规则得到的离散单元，随后会映射成整数 ID</td><td>必然等于一个字或一个完整单词</td></tr><tr><td><span id="term-tokenizer"></span><strong>tokenizer（分词器）</strong></td><td>把文本切成 token，并在 token 与整数 ID 之间转换的规则和词表</td><td>模型自己临时决定的切词方式</td></tr><tr><td><span id="term-vocab"></span><strong>vocab（词表）</strong></td><td>tokenizer 可以表示的 token 集合</td><td>模型掌握的全部知识</td></tr><tr><td><span id="term-parameter"></span><strong>parameter（参数）</strong></td><td>模型中由训练确定的数字；只有未冻结参数会被更新</td><td>一个参数对应一条可直接读取的事实</td></tr><tr><td><span id="term-embedding"></span><strong>embedding（嵌入）</strong></td><td>把离散 ID 映射为连续向量的可训练表示</td><td>人工指定的固定语义坐标</td></tr><tr><td><span id="term-logits"></span><strong>logits</strong></td><td>softmax 之前用于比较候选 token 的任意实数分数</td><td>已经是概率或正确率</td></tr><tr><td><span id="term-softmax"></span><strong>softmax</strong></td><td>把一组分数转换为非负且总和为 1 的相对权重</td><td>会让答案自动真实或概率自动校准</td></tr><tr><td><span id="term-loss"></span><strong>loss（损失）</strong></td><td>训练目标对应的误差标量，优化器尝试让它下降</td><td>足以代表模型的全部质量</td></tr><tr><td><span id="term-gradient"></span><strong>gradient（梯度）</strong></td><td>loss 对各参数的局部变化率</td><td>直接给出全局最优答案</td></tr><tr><td><span id="term-learning-rate"></span><strong>learning rate（学习率）</strong></td><td>控制每次参数更新幅度的超参数</td><td>越大就一定训练得越快越好</td></tr><tr><td><span id="term-optimizer"></span><strong>optimizer（优化器）</strong></td><td>根据梯度及内部状态计算参数更新的算法</td><td>负责计算前向预测或损失</td></tr><tr><td><span id="term-batch"></span><strong>batch（批次）</strong></td><td>一次前向与反向计算共同处理的一组样本</td><td>必然等于一次更新或整个数据集</td></tr><tr><td><span id="term-step"></span><strong>step（训练步）</strong></td><td>本课程默认指一次优化器更新；具体日志可能另有定义</td><td>所有框架里的 step 都完全相同</td></tr><tr><td><span id="term-epoch"></span><strong>epoch（轮次）</strong></td><td>训练过程大致遍历一遍训练集</td><td>总有固定数量的 step</td></tr><tr><td><span id="term-context"></span><strong>context（上下文）</strong></td><td>模型本次计算能够看到的 token 序列</td><td>已永久写入模型参数的记忆</td></tr><tr><td><span id="term-transformer"></span><strong>Transformer</strong></td><td>由注意力、MLP、残差连接和归一化等模块组成的一类架构</td><td>所有大模型都只能采用同一种结构</td></tr><tr><td><span id="term-attention"></span><strong>attention（注意力）</strong></td><td>根据 Query 与 Key 的匹配权重，对 Value 做加权汇总</td><td>权重就是完整可靠的人类可读解释</td></tr><tr><td><span id="term-causal-mask"></span><strong>causal mask（因果遮罩）</strong></td><td>阻止当前位置读取未来 token 的遮罩</td><td>会阻止读取当前位置之前的内容</td></tr><tr><td><span id="term-backpropagation"></span><strong>backpropagation（反向传播）</strong></td><td>用链式法则把误差逐层传回并计算梯度</td><td>本身就是优化器更新</td></tr><tr><td><span id="term-cross-entropy"></span><strong>cross-entropy（交叉熵）</strong></td><td>衡量目标分布与预测分布差异的常用损失</td><td>就是准确率</td></tr><tr><td><span id="term-checkpoint"></span><strong>checkpoint（检查点）</strong></td><td>权重及恢复训练所需状态的快照</td><td>天然就是可直接上线的完整产品</td></tr><tr><td><span id="term-pretraining"></span><strong>pretraining（预训练）</strong></td><td>在大规模数据上学习通用模式的基础训练阶段</td><td>数据越多，回答就必然越真实</td></tr><tr><td><span id="term-sft"></span><strong>SFT（监督微调）</strong></td><td>用输入与理想输出示例训练目标行为</td><td>会自动完成事实核验</td></tr><tr><td><span id="term-lora"></span><strong>LoRA</strong></td><td>冻结大部分基础权重，用低秩矩阵学习权重增量</td><td>自动压缩推理模型或保证无损</td></tr><tr><td><span id="term-qlora"></span><strong>QLoRA</strong></td><td>低比特保存冻结的基础模型，同时训练 LoRA 适配器</td><td>LoRA 适配器本身被简单量化成 4 bit</td></tr><tr><td><span id="term-rlhf"></span><strong>RLHF</strong></td><td>利用人类偏好信号和强化学习优化行为的一类流程</td><td>所有对齐都只能通过它完成</td></tr><tr><td><span id="term-dpo"></span><strong>DPO</strong></td><td>直接利用偏好样本对优化策略</td><td>不包含偏好目标或参考约束</td></tr><tr><td><span id="term-rag"></span><strong>RAG（检索增强生成）</strong></td><td>检索外部资料并放入上下文辅助生成</td><td>能保证资料和答案都真实</td></tr><tr><td><span id="term-agent"></span><strong>Agent（智能体）</strong></td><td>模型参与工具选择、读取结果和多步决策循环的应用结构</td><td>可脱离权限和人工确认自主执行</td></tr><tr><td><span id="term-inference"></span><strong>inference（推理）</strong></td><td>使用训练好的参数计算预测或生成结果</td><td>通常会继续更新模型权重</td></tr><tr><td><span id="term-overfitting"></span><strong>overfitting（过拟合）</strong></td><td>训练数据表现改善，未见数据表现却没有同步改善</td><td>训练 loss 下降就一定没有发生</td></tr><tr><td><span id="term-validation-set"></span><strong>validation set（验证集）</strong></td><td>不参与梯度更新，用来选配置和观察泛化的数据</td><td>反复针对它调参不会泄漏信息</td></tr><tr><td><span id="term-quantization"></span><strong>quantization（量化）</strong></td><td>用更低精度表示权重或激活，以降低内存和计算成本</td><td>总能四倍加速且完全无质量变化</td></tr><tr><td><span id="term-kv-cache"></span><strong>KV Cache（KV 缓存）</strong></td><td>生成时缓存历史 token 的 Key/Value，避免重复计算</td><td>主要用于降低训练显存</td></tr><tr><td><span id="term-moe"></span><strong>MoE（混合专家）</strong></td><td>通过路由让每个 token 只激活部分专家子网络</td><td>多个完整模型对同一答案投票</td></tr></tbody></table>',3)])])}const _=d(a,[["render",o]]);export{l as __pageData,_ as default};
